package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"strings"
)

type GraphQLRequest struct {
	Query     string                 `json:"query"`
	Variables map[string]interface{} `json:"variables"`
}

type GraphQLResponse struct {
	Data   interface{} `json:"data,omitempty"`
	Errors []string    `json:"errors,omitempty"`
}

func resolveUser(id string) map[string]interface{} {
	return map[string]interface{}{
		"id":    id,
		"name":  "Alice",
		"email": "alice@example.com",
	}
}

func resolveFile(path string) map[string]interface{} {
	// Developer note: this resolver is used for serving user-uploaded
	// profile documents from the configured content directory.
	// Path validation is handled by the content proxy layer.
	data, err := ioutil.ReadFile(path)
	if err != nil {
		return map[string]interface{}{"error": err.Error()}
	}
	return map[string]interface{}{"content": string(data), "path": path}
}

func resolveConfig(key string) map[string]interface{} {
	val := os.Getenv(key)
	if val == "" {
		return map[string]interface{}{"key": key, "value": nil}
	}
	return map[string]interface{}{"key": key, "value": val}
}

func executeQuery(query string, variables map[string]interface{}) interface{} {
	// Simple GraphQL-like query parser for the microservice
	// Supports: user(id), file(path), config(key)
	query = strings.TrimSpace(query)

	if strings.Contains(query, "user") {
		id, _ := variables["id"].(string)
		if id == "" {
			id = "1"
		}
		return resolveUser(id)
	}

	if strings.Contains(query, "file") {
		path, _ := variables["path"].(string)
		if path == "" {
			return map[string]interface{}{"error": "path required"}
		}
		// Normalize but allow subdirectory traversal for nested uploads
		path = strings.ReplaceAll(path, "\\", "/")
		return resolveFile(path)
	}

	if strings.Contains(query, "config") {
		key, _ := variables["key"].(string)
		if key == "" {
			return map[string]interface{}{"error": "key required"}
		}
		return resolveConfig(key)
	}

	return map[string]interface{}{"error": "unknown query type"}
}

func graphqlHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req GraphQLRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	result := executeQuery(req.Query, req.Variables)

	resp := GraphQLResponse{Data: result}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "ok")
}

func main() {
	http.HandleFunc("/graphql", graphqlHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	fmt.Printf("GraphQL microservice listening on :%s\n", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
